// Package catalog holds the lists behind search autocomplete: every subject
// USM offers, plus the courses (code + title) and instructors we have seen. The
// snapshot in catalog.json is generated by `replica --catalog` and embedded
// in the API binary; the API adds courses it sees in live search results.
package catalog

import (
	_ "embed"
	"encoding/json"
	"sort"
	"strings"
	"sync"
	"unicode"
)

type Subject struct {
	Subject string `json:"subject"`
	Name    string `json:"name"`
}

type Course struct {
	Subject    string `json:"subject"`
	CatalogNbr string `json:"catalog_nbr"`
	Title      string `json:"title"`
	// Prereqs/Coreqs: every group is required, any one course per group
	// satisfies it (see internal/prereq). Requirement is USM's own wording.
	Prereqs     [][]string `json:"prereqs,omitempty"`
	Coreqs      [][]string `json:"coreqs,omitempty"`
	Requirement string     `json:"requirement,omitempty"`
}

// Instructor is someone listed on at least one section. USM's class search
// filters by last name (instructor_name), so the frontend sends Last.
type Instructor struct {
	First    string   `json:"first"`
	Last     string   `json:"last"`
	Subjects []string `json:"subjects"`
}

type Snapshot struct {
	Subjects    []Subject    `json:"subjects"`
	Courses     []Course     `json:"courses"`
	Instructors []Instructor `json:"instructors"`
}

//go:embed catalog.json
var embedded []byte

// Catalog is safe for concurrent use.
type Catalog struct {
	mu          sync.RWMutex
	subjects    map[string]Subject
	courses     map[string]Course     // key: SUBJECT + " " + CATALOG_NBR
	instructors map[string]Instructor // key: lowercased "first last"
}

// LoadEmbedded builds a Catalog from the snapshot compiled into the binary.
func LoadEmbedded() (*Catalog, error) {
	var snap Snapshot
	if err := json.Unmarshal(embedded, &snap); err != nil {
		return nil, err
	}
	c := &Catalog{subjects: map[string]Subject{}, courses: map[string]Course{}, instructors: map[string]Instructor{}}
	for _, s := range snap.Subjects {
		c.subjects[s.Subject] = s
	}
	for _, co := range snap.Courses {
		c.Add(co)
	}
	for _, in := range snap.Instructors {
		for _, subj := range in.Subjects {
			c.AddInstructor(in.First, in.Last, subj)
		}
	}
	return c, nil
}

// Add records a course; it reports whether the catalog changed.
func (c *Catalog) Add(co Course) bool {
	co.Subject = strings.ToUpper(strings.TrimSpace(co.Subject))
	co.CatalogNbr = strings.ToUpper(strings.TrimSpace(co.CatalogNbr))
	co.Title = strings.TrimSpace(co.Title)
	if co.Subject == "" || co.CatalogNbr == "" || co.Title == "" {
		return false
	}
	key := co.Subject + " " + co.CatalogNbr
	c.mu.Lock()
	defer c.mu.Unlock()
	existing, ok := c.courses[key]
	if ok {
		// live search results carry no prerequisite data; keep what we have
		if co.Prereqs == nil && co.Coreqs == nil && co.Requirement == "" {
			co.Prereqs, co.Coreqs, co.Requirement = existing.Prereqs, existing.Coreqs, existing.Requirement
		}
		if existing.Title == co.Title && co.Requirement == existing.Requirement {
			return false
		}
	}
	c.courses[key] = co
	return true
}

// AddInstructor records that first/last teaches in subject.
func (c *Catalog) AddInstructor(first, last, subject string) {
	first, last = strings.TrimSpace(first), strings.TrimSpace(last)
	subject = strings.ToUpper(strings.TrimSpace(subject))
	if !strings.ContainsFunc(last, unicode.IsLetter) {
		return // placeholders like "-"
	}
	key := strings.ToLower(first + " " + last)
	c.mu.Lock()
	defer c.mu.Unlock()
	in, ok := c.instructors[key]
	if !ok {
		in = Instructor{First: first, Last: last}
	}
	if subject != "" && !contains(in.Subjects, subject) {
		in.Subjects = append(in.Subjects, subject)
		sort.Strings(in.Subjects)
	}
	c.instructors[key] = in
}

func contains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

// Counts returns how many subjects, courses, and instructors the catalog holds.
func (c *Catalog) Counts() (subjects, courses, instructors int) {
	c.mu.RLock()
	defer c.mu.RUnlock()
	return len(c.subjects), len(c.courses), len(c.instructors)
}

// Snapshot returns a sorted copy, suitable for JSON.
func (c *Catalog) Snapshot() Snapshot {
	c.mu.RLock()
	defer c.mu.RUnlock()
	snap := Snapshot{
		Subjects:    make([]Subject, 0, len(c.subjects)),
		Courses:     make([]Course, 0, len(c.courses)),
		Instructors: make([]Instructor, 0, len(c.instructors)),
	}
	for _, in := range c.instructors {
		snap.Instructors = append(snap.Instructors, in)
	}
	sort.Slice(snap.Instructors, func(i, j int) bool {
		a, b := snap.Instructors[i], snap.Instructors[j]
		if a.Last != b.Last {
			return a.Last < b.Last
		}
		return a.First < b.First
	})
	for _, s := range c.subjects {
		snap.Subjects = append(snap.Subjects, s)
	}
	for _, co := range c.courses {
		snap.Courses = append(snap.Courses, co)
	}
	sort.Slice(snap.Subjects, func(i, j int) bool { return snap.Subjects[i].Subject < snap.Subjects[j].Subject })
	sort.Slice(snap.Courses, func(i, j int) bool {
		a, b := snap.Courses[i], snap.Courses[j]
		if a.Subject != b.Subject {
			return a.Subject < b.Subject
		}
		return a.CatalogNbr < b.CatalogNbr
	})
	return snap
}
